int B = 1;
int r = 0;
int d = 0;
int p = 0;
int q = 0;
r = A;
d = B;
p = 1;
q = 0;
while (1)
{
  if (!(d == (B * p)))
    break;
  d = 2 * d;
  p = 2 * p;
}

while (1)
{
  if (!(A == ((q * B) + r)))
    break;
  d = d / 2;
  p = p / 2;
  if (r >= d)
  {
    r = r - d;
    q = q + p;
  }
}

return 0;
}


